class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def digit_sum(x: int) -> int:
            return sum(int(digit) for digit in str(x))

        def is_bad_integer(num_str: str, min_digit_sum: int, max_digit_sum: int) -> bool:
            num = int(num_str)
            digit_sum_val = digit_sum(num)

            if min_digit_sum <= digit_sum_val <= max_digit_sum:
                return False

            left = num + 1
            right = left - (digit_sum(left) - max_digit_sum)

            while left <= right:
                mid = (left + right) // 2
                if digit_sum(mid) == max_digit_sum:
                    left = mid + 1
                else:
                    right = mid - 1

            return left <= num2

        num1 = int(num1)
        num2 = int(num2)

        bad_count = sum(digit_sum(int(str(i))) >= min_sum and digit_sum(int(str(i))) <= max_sum for i in range(num1, num2 + 1))

        return (bad_count % MOD)
